      SUBROUTINE FZERO      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'C      DO 100 NUM = 1, NEL      I = ISTOR(NUM)      TYPE = IDATA(I)      IF (TYPE .EQ. 10) THEN        DATA(I+5) = 0.0        DATA(I+6) = 0.0      ENDIF  100 CONTINUEC      RETURN      END